export const EMBEDDED_COMPANION_PHP_TEMPLATE: string = "<?php\r\n/**\r\n * ============================================================================\r\n * Bentian ERP Bridge — Conector Web Universal (HTTPS Bridge v1.1.0)\r\n * ============================================================================\r\n * Puerto: 443 (HTTPS Seguro)\r\n * Protocolo: HMAC-SHA256 / Bearer Token\r\n * Requisitos: PHP 7.4 o superior, PDO MariaDB / MySQL\r\n * Ubicación en Plesk: httpdocs/erp-bridge-endpoint.php\r\n * ============================================================================\r\n */\r\n\r\n// Desactivar salida de errores HTML para garantizar JSON estricto\r\nerror_reporting(0);\r\nini_set('display_errors', '0');\r\n\r\nheader('Content-Type: application/json; charset=utf-8');\r\nheader('X-Content-Type-Options: nosniff');\r\nheader('X-Frame-Options: DENY');\r\nheader('Access-Control-Allow-Origin: *');\r\nheader('Access-Control-Allow-Methods: GET, POST, OPTIONS');\r\nheader('Access-Control-Allow-Headers: Content-Type, Authorization, X-Bridge-Key, X-Bentian-Signature, X-Bentian-Timestamp, X-Bentian-Agent-Version, Idempotency-Key, X-File-Path, X-Product-SKU');\r\n\r\nif ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') {\r\n    http_response_code(204);\r\n    exit;\r\n}\r\n\r\n// ============================================================================\r\n// ⚠️ ATENCIÓN: CONFIGURACIÓN PARA EL PROGRAMADOR WEB / ADMINISTRADOR DE HOSTING\r\n// ============================================================================\r\n// SOLO TIENES QUE RELLENAR ESTAS 4 LÍNEAS CON LOS DATOS DE TU BASE DE DATOS:\r\n// (La clave secreta EB_SECRET_KEY ya viene configurada por Bentian ERP Bridge)\r\n// ============================================================================\r\n\r\ndefine('EB_SECRET_KEY', getenv('EB_SECRET_KEY') ?: '%%EB_SECRET_KEY%%');\r\ndefine('EB_DB_HOST',    getenv('EB_DB_HOST')    ?: '%%EB_DB_HOST%%');   // Habitualmente 'localhost' o '127.0.0.1'\r\ndefine('EB_DB_NAME',    getenv('EB_DB_NAME')    ?: '%%EB_DB_NAME%%');   // Nombre de la base de datos de tu tienda web\r\ndefine('EB_DB_USER',    getenv('EB_DB_USER')    ?: '%%EB_DB_USER%%');   // Usuario con permisos en MySQL / MariaDB\r\ndefine('EB_DB_PASS',    getenv('EB_DB_PASS')    ?: '%%EB_DB_PASS%%');   // Contraseña de MySQL / MariaDB\r\n\r\n// ============================================================================\r\n// 🛑 NO MODIFICAR NADA POR DEBAJO DE ESTA LÍNEA\r\n// El resto del archivo es el motor automático de sincronización con Factusol.\r\n// Al ejecutarse por primera vez, el archivo creará automáticamente las tablas\r\n// necesarias (eb_products, eb_stock, eb_orders) de forma 100% idempotente y segura.\r\n// ============================================================================\r\n\r\n// ----------------------------------------------------------------------------\r\n// 2. CONEXIÓN PDO A MARIADB / MYSQL LOCAL\r\n// ----------------------------------------------------------------------------\r\nfunction getDbConnection(&$errorMsg = null) {\r\n    static $pdo = null;\r\n    if ($pdo !== null) return $pdo;\r\n\r\n    if (empty(EB_DB_NAME)) {\r\n        $errorMsg = 'Nombre de base de datos no configurado (EB_DB_NAME está vacío)';\r\n        return null;\r\n    }\r\n\r\n    $hosts = [EB_DB_HOST];\r\n    if (EB_DB_HOST === '127.0.0.1') $hosts[] = 'localhost';\r\n    else if (EB_DB_HOST === 'localhost') $hosts[] = '127.0.0.1';\r\n\r\n    $lastException = null;\r\n    foreach ($hosts as $h) {\r\n        try {\r\n            $dsn = \"mysql:host=\" . $h . \";dbname=\" . EB_DB_NAME . \";charset=utf8mb4\";\r\n            $options = [\r\n                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,\r\n                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,\r\n                PDO::ATTR_EMULATE_PREPARES => false,\r\n            ];\r\n            $pdo = new PDO($dsn, EB_DB_USER, EB_DB_PASS, $options);\r\n            return $pdo;\r\n        } catch (Exception $e) {\r\n            $lastException = $e;\r\n        }\r\n    }\r\n\r\n    $errorMsg = 'Error al conectar con MariaDB/MySQL';\r\n    return null;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// 3. AUTO-INSTALACIÓN DE TABLAS CANÓNICAS (IDEMPOTENTE - NUNCA BORRA DATOS)\r\n// ----------------------------------------------------------------------------\r\nfunction ensureTablesExist($pdo) {\r\n    if (!$pdo) return false;\r\n    try {\r\n        $pdo->exec(\"\r\n            CREATE TABLE IF NOT EXISTS `eb_products` (\r\n              `code` VARCHAR(50) NOT NULL PRIMARY KEY,\r\n              `sku` VARCHAR(50) DEFAULT NULL,\r\n              `name` VARCHAR(255) NOT NULL,\r\n              `description` TEXT DEFAULT NULL,\r\n              `section_code` VARCHAR(10) DEFAULT NULL,\r\n              `section_name` VARCHAR(100) DEFAULT NULL,\r\n              `family_code` VARCHAR(10) DEFAULT NULL,\r\n              `family_name` VARCHAR(100) DEFAULT NULL,\r\n              `price` DECIMAL(12, 4) NOT NULL DEFAULT 0.0000,\r\n              `sale_price` DECIMAL(12, 4) DEFAULT NULL,\r\n              `vat_rate` DECIMAL(5, 2) NOT NULL DEFAULT 21.00,\r\n              `price_with_vat` DECIMAL(12, 4) NOT NULL DEFAULT 0.0000,\r\n              `sale_price_with_vat` DECIMAL(12, 4) DEFAULT NULL,\r\n              `unit_of_measure` VARCHAR(20) DEFAULT 'UNIDADES',\r\n              `weight` DECIMAL(10, 3) DEFAULT 0.000,\r\n              `barcode` VARCHAR(50) DEFAULT NULL,\r\n              `imgart` VARCHAR(255) DEFAULT NULL,\r\n              `image_url` VARCHAR(500) DEFAULT NULL,\r\n              `active` TINYINT(1) NOT NULL DEFAULT 1,\r\n              `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\r\n              INDEX `idx_family` (`family_code`),\r\n              INDEX `idx_active` (`active`)\r\n            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\r\n\r\n            CREATE TABLE IF NOT EXISTS `eb_stock` (\r\n              `code` VARCHAR(50) NOT NULL PRIMARY KEY,\r\n              `stock` DECIMAL(12, 3) NOT NULL DEFAULT 0.000,\r\n              `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\r\n              INDEX `idx_stock_val` (`stock`)\r\n            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\r\n\r\n            CREATE TABLE IF NOT EXISTS `eb_orders` (\r\n              `id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY,\r\n              `order_number` VARCHAR(50) NOT NULL UNIQUE,\r\n              `status` ENUM('PENDING', 'SYNCED', 'CANCELLED') NOT NULL DEFAULT 'PENDING',\r\n              `customer_data` LONGTEXT NOT NULL,\r\n              `order_lines` LONGTEXT NOT NULL,\r\n              `payment_method` VARCHAR(50) NOT NULL,\r\n              `payment_status` VARCHAR(50) NOT NULL,\r\n              `payment_reference` VARCHAR(100) DEFAULT NULL,\r\n              `subtotal` DECIMAL(12, 2) NOT NULL,\r\n              `tax_total` DECIMAL(12, 2) NOT NULL,\r\n              `shipping_cost` DECIMAL(12, 2) NOT NULL DEFAULT 0.00,\r\n              `total` DECIMAL(12, 2) NOT NULL,\r\n              `factusol_order_number` INT DEFAULT NULL,\r\n              `factusol_series` VARCHAR(5) DEFAULT NULL,\r\n              `factusol_unstocked` TINYINT(1) NOT NULL DEFAULT 0,\r\n              `unstocked_at` TIMESTAMP NULL DEFAULT NULL,\r\n              `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\r\n              `synced_at` TIMESTAMP NULL DEFAULT NULL,\r\n              INDEX `idx_status` (`status`),\r\n              INDEX `idx_unstocked` (`status`, `factusol_unstocked`),\r\n              INDEX `idx_created` (`created_at`)\r\n            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\r\n        \");\r\n        try {\r\n            $pdo->exec(\"ALTER TABLE `eb_products` ADD COLUMN IF NOT EXISTS `sale_price` DECIMAL(12, 4) DEFAULT NULL\");\r\n            $pdo->exec(\"ALTER TABLE `eb_products` ADD COLUMN IF NOT EXISTS `sale_price_with_vat` DECIMAL(12, 4) DEFAULT NULL\");\r\n            $pdo->exec(\"ALTER TABLE `eb_products` ADD COLUMN IF NOT EXISTS `imgart` VARCHAR(255) DEFAULT NULL\");\r\n            $pdo->exec(\"ALTER TABLE `eb_products` ADD COLUMN IF NOT EXISTS `image_url` VARCHAR(500) DEFAULT NULL\");\r\n        } catch (Exception $colErr) {}\r\n        try {\r\n            $pdo->exec(\"ALTER TABLE `eb_orders` ADD COLUMN IF NOT EXISTS `factusol_unstocked` TINYINT(1) NOT NULL DEFAULT 0\");\r\n            $pdo->exec(\"ALTER TABLE `eb_orders` ADD COLUMN IF NOT EXISTS `unstocked_at` TIMESTAMP NULL DEFAULT NULL\");\r\n        } catch (Exception $orderColErr) {\r\n            try {\r\n                $cols = $pdo->query(\"SHOW COLUMNS FROM `eb_orders` LIKE 'factusol_unstocked'\")->fetchAll();\r\n                if (empty($cols)) {\r\n                    $pdo->exec(\"ALTER TABLE `eb_orders` ADD COLUMN `factusol_unstocked` TINYINT(1) NOT NULL DEFAULT 0\");\r\n                }\r\n            } catch (Exception $e1) {}\r\n            try {\r\n                $cols = $pdo->query(\"SHOW COLUMNS FROM `eb_orders` LIKE 'unstocked_at'\")->fetchAll();\r\n                if (empty($cols)) {\r\n                    $pdo->exec(\"ALTER TABLE `eb_orders` ADD COLUMN `unstocked_at` TIMESTAMP NULL DEFAULT NULL\");\r\n                }\r\n            } catch (Exception $e2) {}\r\n        }\r\n        return true;\r\n    } catch (Exception $e) {\r\n        return false;\r\n    }\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// 4. DIRECTORIO BASE PARA IMÁGENES PÚBLICAS\r\n// ----------------------------------------------------------------------------\r\nfunction getPublicImagesBaseDir() {\r\n    $candidates = [\r\n        __DIR__ . '/assets/img/factusolImg',\r\n        __DIR__ . '/tienda/assets/img/factusolImg',\r\n        dirname(__DIR__) . '/tienda/assets/img/factusolImg',\r\n        __DIR__ . '/uploads/products',\r\n    ];\r\n    foreach ($candidates as $cand) {\r\n        if (is_dir($cand)) {\r\n            return $cand;\r\n        }\r\n    }\r\n    $defaultDir = __DIR__ . '/assets/img/factusolImg';\r\n    if (!is_dir($defaultDir)) {\r\n        @mkdir($defaultDir, 0755, true);\r\n    }\r\n    return $defaultDir;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// 5. AUTENTICACIÓN Y SEGURIDAD HMAC-SHA256 / BEARER / X-BRIDGE-KEY\r\n// ----------------------------------------------------------------------------\r\nfunction verifyAuthentication() {\r\n    $secret = EB_SECRET_KEY;\r\n    if (empty($secret) || strpos($secret, '%%EB_SECRET_KEY%%') !== false || strlen($secret) < 16) {\r\n        http_response_code(503);\r\n        echo json_encode(['error' => 'Endpoint no configurado: Clave secreta no establecida o insegura (EB_SECRET_KEY debe configurarse con al menos 16 caracteres)']);\r\n        exit;\r\n    }\r\n\r\n    $headers = function_exists('getallheaders') ? getallheaders() : [];\r\n    $authHeader = isset($headers['Authorization']) ? $headers['Authorization'] : (isset($_SERVER['HTTP_AUTHORIZATION']) ? $_SERVER['HTTP_AUTHORIZATION'] : '');\r\n    $bridgeKeyHeader = isset($headers['X-Bridge-Key']) ? $headers['X-Bridge-Key'] : (isset($headers['x-bridge-key']) ? $headers['x-bridge-key'] : (isset($_SERVER['HTTP_X_BRIDGE_KEY']) ? $_SERVER['HTTP_X_BRIDGE_KEY'] : ''));\r\n    $signature = isset($headers['X-Bentian-Signature']) ? $headers['X-Bentian-Signature'] : (isset($_SERVER['HTTP_X_BENTIAN_SIGNATURE']) ? $_SERVER['HTTP_X_BENTIAN_SIGNATURE'] : '');\r\n    $timestamp = isset($headers['X-Bentian-Timestamp']) ? intval($headers['X-Bentian-Timestamp']) : (isset($_SERVER['HTTP_X_BENTIAN_TIMESTAMP']) ? intval($_SERVER['HTTP_X_BENTIAN_TIMESTAMP']) : 0);\r\n\r\n    // 1. Bearer Token\r\n    if ($authHeader && preg_match('/Bearer\\s+(.*)$/i', $authHeader, $matches)) {\r\n        if (hash_equals($secret, trim($matches[1]))) {\r\n            return true;\r\n        }\r\n    }\r\n\r\n    // 2. Cabecera X-Bridge-Key (alternativa sin prefijo Bearer)\r\n    if ($bridgeKeyHeader && hash_equals($secret, trim($bridgeKeyHeader))) {\r\n        return true;\r\n    }\r\n\r\n    // 3. Firma HMAC-SHA256\r\n    if ($signature && $timestamp > 0) {\r\n        if (abs(time() - $timestamp) > 300) {\r\n            http_response_code(401);\r\n            echo json_encode(['error' => 'Timestamp expirado (desfase superior a 5 minutos)']);\r\n            exit;\r\n        }\r\n        $rawPayload = file_get_contents('php://input');\r\n        $expectedSignature = hash_hmac('sha256', $timestamp . $rawPayload, $secret);\r\n        if (hash_equals($expectedSignature, $signature)) {\r\n            return true;\r\n        }\r\n    }\r\n\r\n    http_response_code(401);\r\n    echo json_encode(['error' => 'Firma o token de autorización no válido. Se requiere cabecera Authorization: Bearer <secret> o X-Bridge-Key: <secret>']);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// 6. ENRUTADOR DE ACCIONES (Compatible con Query Params y PATH_INFO de Angular)\r\n// ----------------------------------------------------------------------------\r\n$requestUri = $_SERVER['REQUEST_URI'] ?? '';\r\n$pathInfo = $_SERVER['PATH_INFO'] ?? '';\r\n$uriPath = parse_url($requestUri, PHP_URL_PATH) ?? '';\r\n\r\n$route = '';\r\nif (!empty($_GET['action'])) {\r\n    $route = trim($_GET['action']);\r\n} else if (!empty($pathInfo)) {\r\n    $route = trim($pathInfo, '/');\r\n} else if (preg_match('#/erp-bridge-endpoint\\.php(?:/([^?]+))?#i', $uriPath, $m)) {\r\n    $route = isset($m[1]) ? trim($m[1], '/') : '';\r\n}\r\n\r\n$routeParts = explode('/', $route);\r\n$mainAction = strtolower($routeParts[0] ?? '');\r\n$routeParam = $routeParts[1] ?? '';\r\n\r\nif (empty($mainAction)) {\r\n    $mainAction = ($_SERVER['REQUEST_METHOD'] === 'POST') ? 'create_order' : 'ping';\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// RUTA PÚBLICA: PING / HEALTH\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'ping' || $mainAction === 'health') {\r\n    $dbErr = null;\r\n    $pdo = getDbConnection($dbErr);\r\n    $tablesOk = false;\r\n    $articleCount = 0;\r\n    if ($pdo) {\r\n        try {\r\n            $checkStmt = $pdo->query(\"SHOW TABLES LIKE 'eb_products'\");\r\n            $tablesOk = ($checkStmt && $checkStmt->rowCount() > 0);\r\n            if ($tablesOk) {\r\n                $countStmt = $pdo->query(\"SELECT COUNT(*) FROM `eb_products`\");\r\n                $articleCount = (int)$countStmt->fetchColumn();\r\n            }\r\n        } catch (Exception $e) {\r\n            $tablesOk = false;\r\n        }\r\n    }\r\n\r\n    $baseImgDir = getPublicImagesBaseDir();\r\n\r\n    echo json_encode([\r\n        'status' => 'ok',\r\n        'success' => true,\r\n        'service' => 'Bentian ERP Bridge Universal Web Connector',\r\n        'version' => '1.1.0',\r\n        'latestAgentVersion' => '0.2.6',\r\n        'phpVersion' => PHP_VERSION,\r\n        'databaseConnected' => ($pdo !== null),\r\n        'tablesReady' => $tablesOk,\r\n        'articleCount' => $articleCount,\r\n        'imagesSupported' => true,\r\n        'imagesDirectory' => basename($baseImgDir),\r\n        'database' => [\r\n            'connected' => ($pdo !== null),\r\n            'tablesReady' => $tablesOk,\r\n            'articleCount' => $articleCount,\r\n        ],\r\n        'timestamp' => time(),\r\n        'https' => (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (isset($_SERVER['SERVER_PORT']) && $_SERVER['SERVER_PORT'] == 443),\r\n    ]);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// RUTA PÚBLICA: AUTO-UPDATE MANIFEST PROXY / FALLBACK\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'check_update' || $mainAction === 'update_manifest') {\r\n    $remoteManifestUrl = 'https://bridge.cristianjm.com/releases/latest.json';\r\n    $ctx = stream_context_create([\r\n        'http' => [\r\n            'timeout' => 5,\r\n            'user_agent' => 'Bentian-Universal-Bridge/1.1.0',\r\n        ],\r\n        'ssl' => [\r\n            'verify_peer' => true,\r\n            'verify_peer_name' => true,\r\n        ]\r\n    ]);\r\n    $content = @file_get_contents($remoteManifestUrl, false, $ctx);\r\n    if ($content !== false && !empty($content)) {\r\n        echo $content;\r\n    } else {\r\n        echo json_encode([\r\n            'latestVersion' => '0.2.6',\r\n            'publishedAt' => '2026-09-18T16:57:52.351Z',\r\n            'stable' => [\r\n                'version' => '0.2.6',\r\n                'channel' => 'stable',\r\n                'platform' => 'win32_x64',\r\n                'downloadUrl' => 'https://bridge.cristianjm.com/releases/v0.2.6/BentianAgent.exe',\r\n                'sha256' => '46ddeaf2a78c7c0723dae00707197c96beaa988b390b34a22c4da58397c2c8d2',\r\n                'signature' => '4Dpouas2UntXny6lqfEVsQwSvG5rb/0t1l/PWQVZT13AVmhlnjdi82X4Wz65Az8vIO7xv/uoyIp8Bt9EpTA/BA==',\r\n                'fileSize' => 91718656,\r\n                'releaseNotes' => 'Lanzamiento oficial Bentian Agent v0.2.6 - Sincronización Factusol & WooCommerce',\r\n                'mandatory' => false,\r\n                'minVersion' => '0.1.0',\r\n            ]\r\n        ]);\r\n    }\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// RUTA PÚBLICA: TARIFAS (Compatible con RatesService de Angular)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'rates') {\r\n    echo json_encode([\r\n        [\r\n            'codtar' => 'INTERNET',\r\n            'destar' => 'INTERNET',\r\n            'martar' => '0',\r\n            'ivatar' => '21',\r\n            'diitar' => '0',\r\n        ]\r\n    ]);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// RUTA PÚBLICA: SECCIONES (Compatible con SectionService de Angular)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'secction' || $mainAction === 'sections') {\r\n    $pdo = getDbConnection();\r\n    if (!$pdo) {\r\n        echo json_encode([]);\r\n        exit;\r\n    }\r\n    ensureTablesExist($pdo);\r\n    $stmt = $pdo->query(\"\r\n        SELECT DISTINCT \r\n            section_code AS codsec, \r\n            COALESCE(section_name, section_code) AS dessec \r\n        FROM eb_products \r\n        WHERE section_code IS NOT NULL AND section_code != '' \r\n        ORDER BY section_code ASC\r\n    \");\r\n    $sections = $stmt->fetchAll();\r\n    echo json_encode($sections);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// RUTA PÚBLICA: FAMILIAS Y ARTÍCULOS POR FAMILIA (Compatible con FamilyService)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'family' || $mainAction === 'families') {\r\n    $pdo = getDbConnection();\r\n    if (!$pdo) {\r\n        echo json_encode([]);\r\n        exit;\r\n    }\r\n    ensureTablesExist($pdo);\r\n\r\n    $famId = !empty($routeParam) ? trim($routeParam) : (isset($_GET['id']) ? trim($_GET['id']) : (isset($_GET['famId']) ? trim($_GET['famId']) : ''));\r\n\r\n    if (!empty($famId)) {\r\n        // Artículos de una familia específica\r\n        $stmt = $pdo->prepare(\"\r\n            SELECT \r\n                p.code AS codart,\r\n                p.name AS desart,\r\n                p.description AS dewart,\r\n                p.price AS pcoart,\r\n                p.sale_price AS sale_price,\r\n                p.price_with_vat AS pvp,\r\n                p.sale_price_with_vat AS sale_pvp,\r\n                p.family_code AS famart,\r\n                p.barcode AS eanart,\r\n                p.unit_of_measure AS measure,\r\n                p.vat_rate AS tivart,\r\n                IF(p.imgart IS NOT NULL AND p.imgart != '', \r\n                   IF(p.imgart LIKE '/%', p.imgart, CONCAT('/', p.imgart)), \r\n                   '') AS imgart,\r\n                p.image_url AS image_url,\r\n                COALESCE(s.stock, 0) AS stock \r\n            FROM eb_products p \r\n            LEFT JOIN eb_stock s ON p.code = s.code \r\n            WHERE p.active = 1 AND p.family_code = :famId\r\n            ORDER BY p.name ASC\r\n        \");\r\n        $stmt->execute([':famId' => $famId]);\r\n        echo json_encode($stmt->fetchAll());\r\n        exit;\r\n    } else {\r\n        // Listado de familias\r\n        $stmt = $pdo->query(\"\r\n            SELECT DISTINCT \r\n                family_code AS codfam, \r\n                COALESCE(family_name, family_code) AS desfam \r\n            FROM eb_products \r\n            WHERE family_code IS NOT NULL AND family_code != '' \r\n            ORDER BY family_code ASC\r\n        \");\r\n        echo json_encode($stmt->fetchAll());\r\n        exit;\r\n    }\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// RUTA PÚBLICA: CATÁLOGO COMPLETO Y MEDIDAS (Compatible con DataService)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'catalog' || $mainAction === 'articles') {\r\n    $pdo = getDbConnection();\r\n    if (!$pdo) {\r\n        http_response_code(503);\r\n        echo json_encode(['error' => 'Base de datos no disponible']);\r\n        exit;\r\n    }\r\n    ensureTablesExist($pdo);\r\n\r\n    // Búsqueda opcional\r\n    $searchQuery = isset($_GET['query']) ? trim($_GET['query']) : '';\r\n    $where = \"WHERE p.active = 1\";\r\n    $params = [];\r\n    if (!empty($searchQuery)) {\r\n        $where .= \" AND (p.name LIKE :q1 OR p.code LIKE :q2 OR p.barcode LIKE :q3 OR p.description LIKE :q4)\";\r\n        $searchTerm = '%' . $searchQuery . '%';\r\n        $params[':q1'] = $searchTerm;\r\n        $params[':q2'] = $searchTerm;\r\n        $params[':q3'] = $searchTerm;\r\n        $params[':q4'] = $searchTerm;\r\n    }\r\n\r\n    $stmt = $pdo->prepare(\"\r\n        SELECT \r\n            p.code AS codart,\r\n            p.name AS desart,\r\n            p.description AS dewart,\r\n            p.price AS pcoart,\r\n            p.sale_price AS sale_price,\r\n            p.price_with_vat AS pvp,\r\n            p.sale_price_with_vat AS sale_pvp,\r\n            p.family_code AS famart,\r\n            p.barcode AS eanart,\r\n            p.unit_of_measure AS measure,\r\n            p.vat_rate AS tivart,\r\n            IF(p.imgart IS NOT NULL AND p.imgart != '', \r\n               IF(p.imgart LIKE '/%', p.imgart, CONCAT('/', p.imgart)), \r\n               '') AS imgart,\r\n            p.image_url AS image_url,\r\n            p.active,\r\n            p.section_code,\r\n            p.section_name,\r\n            p.family_name,\r\n            COALESCE(s.stock, 0) AS stock \r\n        FROM eb_products p \r\n        LEFT JOIN eb_stock s ON p.code = s.code \r\n        {$where}\r\n        ORDER BY p.name ASC\r\n    \");\r\n    $stmt->execute($params);\r\n    $items = $stmt->fetchAll();\r\n\r\n    $stmtMeasures = $pdo->query(\"SELECT DISTINCT unit_of_measure FROM eb_products WHERE unit_of_measure IS NOT NULL AND unit_of_measure != ''\");\r\n    $rawMeasures = $stmtMeasures->fetchAll(PDO::FETCH_COLUMN) ?: ['UNIDADES'];\r\n    $measures = [];\r\n    foreach ($rawMeasures as $m) {\r\n        $measures[] = ['desume' => $m];\r\n    }\r\n\r\n    if (!empty($searchQuery)) {\r\n        // En búsqueda devuelve array directo de artículos\r\n        echo json_encode($items);\r\n    } else {\r\n        echo json_encode(['success' => true, 'count' => count($items), 'articles' => $items, 'measures' => $measures]);\r\n    }\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// RUTA PÚBLICA: MEDIDAS\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'measures') {\r\n    $pdo = getDbConnection();\r\n    if (!$pdo) {\r\n        echo json_encode(['measures' => [['desume' => 'UNIDADES']]]);\r\n        exit;\r\n    }\r\n    ensureTablesExist($pdo);\r\n    $stmt = $pdo->query(\"SELECT DISTINCT unit_of_measure FROM eb_products WHERE unit_of_measure IS NOT NULL AND unit_of_measure != ''\");\r\n    $rawMeasures = $stmt->fetchAll(PDO::FETCH_COLUMN) ?: ['UNIDADES'];\r\n    $measures = [];\r\n    foreach ($rawMeasures as $m) {\r\n        $measures[] = ['desume' => $m];\r\n    }\r\n    echo json_encode(['measures' => $measures]);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// RUTA PÚBLICA: CREACIÓN DE PEDIDOS (Checkout de la tienda)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'create_order' || $mainAction === 'order') {\r\n    $pdo = getDbConnection();\r\n    if (!$pdo) {\r\n        http_response_code(503);\r\n        echo json_encode(['error' => 'Base de datos no disponible']);\r\n        exit;\r\n    }\r\n    ensureTablesExist($pdo);\r\n\r\n    $rawBody = file_get_contents('php://input');\r\n    $payload = json_decode($rawBody, true) ?: [];\r\n\r\n    $shipping = $payload['shippingData'] ?? [];\r\n    $orderData = $payload['order'] ?? [];\r\n    $lines = $orderData['lines'] ?? $orderData['lineas'] ?? $payload['lines'] ?? $payload['lineas'] ?? [];\r\n\r\n    if (!is_array($lines) || count($lines) === 0) {\r\n        http_response_code(400);\r\n        echo json_encode(['error' => 'El pedido debe contener al menos una línea de artículo']);\r\n        exit;\r\n    }\r\n\r\n    // Límite máximo de líneas de pedido para prevenir DoS en base de datos\r\n    if (count($lines) > 200) {\r\n        http_response_code(400);\r\n        echo json_encode(['error' => 'El pedido supera el límite máximo permitido de 200 líneas']);\r\n        exit;\r\n    }\r\n\r\n    $total = floatval($orderData['total'] ?? $orderData['cabecera']['totpcl'] ?? $payload['total'] ?? 0);\r\n    $subtotal = floatval($orderData['subtotal'] ?? $orderData['cabecera']['net1pcl'] ?? $payload['subtotal'] ?? $total);\r\n    $taxTotal = floatval($orderData['taxTotal'] ?? $orderData['cabecera']['iiva1pcl'] ?? $payload['taxTotal'] ?? 0);\r\n    $shippingCost = floatval($payload['shippingCost'] ?? 0);\r\n\r\n    // Validación estricta de importes numéricos positivos y razonables\r\n    if ($total < 0 || $subtotal < 0 || $taxTotal < 0 || $shippingCost < 0 ||\r\n        $total > 1000000 || $subtotal > 1000000 || $taxTotal > 500000 || $shippingCost > 10000 ||\r\n        !is_finite($total) || !is_finite($subtotal) || !is_finite($taxTotal) || !is_finite($shippingCost)) {\r\n        http_response_code(400);\r\n        echo json_encode(['error' => 'Importes de pedido no válidos o fuera de rango permitido']);\r\n        exit;\r\n    }\r\n\r\n    // Validación de cantidades y precios en cada línea\r\n    foreach ($lines as $idx => $line) {\r\n        if (!is_array($line)) {\r\n            http_response_code(400);\r\n            echo json_encode(['error' => \"Formato no válido en la línea {$idx} del pedido\"]);\r\n            exit;\r\n        }\r\n        $qty = floatval($line['canlpc'] ?? $line['quantity'] ?? $line['qty'] ?? $line['unidades'] ?? 1);\r\n        if ($qty <= 0 || $qty > 100000 || !is_finite($qty)) {\r\n            http_response_code(400);\r\n            echo json_encode(['error' => \"Cantidad no válida en la línea {$idx} del pedido\"]);\r\n            exit;\r\n        }\r\n        $linePrice = floatval($line['prelpc'] ?? $line['price'] ?? $line['precio'] ?? 0);\r\n        if ($linePrice < 0 || $linePrice > 1000000 || !is_finite($linePrice)) {\r\n            http_response_code(400);\r\n            echo json_encode(['error' => \"Precio no válido en la línea {$idx} del pedido\"]);\r\n            exit;\r\n        }\r\n    }\r\n\r\n    // No confiar ciegamente en paymentStatus: 'COMPLETED' enviado desde el cliente web.\r\n    // El estado inicial del pedido web debe ser PENDING_PAYMENT salvo que provenga de pasarela verificada.\r\n    $rawPayStatus = strtoupper(trim(strval($payload['paymentStatus'] ?? '')));\r\n    $payStatus = 'PENDING_PAYMENT';\r\n    if ($rawPayStatus === 'PENDING' || $rawPayStatus === 'PENDING_PAYMENT' || $rawPayStatus === 'ON_HOLD') {\r\n        $payStatus = $rawPayStatus;\r\n    }\r\n\r\n    $orderNumber = 'WEB-' . date('Ymd') . '-' . strtoupper(substr(uniqid(), -5));\r\n\r\n    $stmt = $pdo->prepare(\"\r\n        INSERT INTO `eb_orders`\r\n          (`order_number`, `status`, `customer_data`, `order_lines`, `payment_method`, `payment_status`, `payment_reference`, `subtotal`, `tax_total`, `shipping_cost`, `total`, `created_at`)\r\n        VALUES\r\n          (:orderNum, 'PENDING', :custData, :linesData, :payMethod, :payStatus, :payRef, :subtotal, :taxTotal, :shipCost, :total, NOW())\r\n    \");\r\n\r\n    $success = $stmt->execute([\r\n        ':orderNum' => $orderNumber,\r\n        ':custData' => json_encode($shipping, JSON_UNESCAPED_UNICODE),\r\n        ':linesData' => json_encode($lines, JSON_UNESCAPED_UNICODE),\r\n        ':payMethod' => substr($payload['paymentMethod'] ?? $payload['paymentMethodType'] ?? 'paypal', 0, 50),\r\n        ':payStatus' => substr($payStatus, 0, 50),\r\n        ':payRef' => substr($payload['paymentReference'] ?? $payload['paymentMethodId'] ?? '', 0, 100),\r\n        ':subtotal' => $subtotal,\r\n        ':taxTotal' => $taxTotal,\r\n        ':shipCost' => $shippingCost,\r\n        ':total' => $total,\r\n    ]);\r\n\r\n    $newId = $pdo->lastInsertId();\r\n    echo json_encode([\r\n        'success' => $success,\r\n        'pedidoId' => intval($newId),\r\n        'orderNumber' => $orderNumber,\r\n        'message' => 'Pedido registrado correctamente en espera de Factusol',\r\n    ]);\r\n    exit;\r\n}\r\n\r\n// ============================================================================\r\n// ACCIONES PROTEGIDAS DEL AGENTE LOCAL Y WEBHOOKS AUTENTICADOS (Requieren Secret Key)\r\n// ============================================================================\r\nverifyAuthentication();\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA / WEBHOOK AUTENTICADO: CANCELACIÓN DE PEDIDOS (Pasarelas / Agente)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'cancel_order' || $mainAction === 'order_cancel' || $mainAction === 'cancel' || $mainAction === 'payment_webhook' || $mainAction === 'webhook') {\r\n    $pdo = getDbConnection();\r\n    if (!$pdo) {\r\n        http_response_code(503);\r\n        echo json_encode(['error' => 'Base de datos no disponible']);\r\n        exit;\r\n    }\r\n    ensureTablesExist($pdo);\r\n\r\n    $rawBody = file_get_contents('php://input');\r\n    $payload = json_decode($rawBody, true) ?: [];\r\n\r\n    // Si es un webhook de Stripe/PayPal/Redsys, verificar si corresponde a reembolso o cancelación\r\n    $isWebhook = ($mainAction === 'webhook' || $mainAction === 'payment_webhook');\r\n    if ($isWebhook) {\r\n        $eventType = strtolower($payload['type'] ?? $payload['event_type'] ?? $payload['event'] ?? '');\r\n        $eventStatus = strtolower($payload['status'] ?? '');\r\n        $isCancellationEvent = (\r\n            strpos($eventType, 'refund') !== false ||\r\n            strpos($eventType, 'cancel') !== false ||\r\n            strpos($eventType, 'denied') !== false ||\r\n            in_array($eventStatus, ['cancelled', 'canceled', 'refunded', 'denied', 'failed'])\r\n        );\r\n        if (!$isCancellationEvent && empty($_GET['order_number']) && empty($payload['orderNumber'])) {\r\n            echo json_encode(['status' => 'ignored', 'message' => 'Evento de webhook no relacionado con cancelación o reembolso']);\r\n            exit;\r\n        }\r\n    }\r\n\r\n    $orderNum = trim(strval($payload['orderNumber'] ?? $payload['order_number'] ?? $payload['data']['object']['metadata']['order_number'] ?? $_GET['order_number'] ?? $_GET['orderNumber'] ?? ''));\r\n    $orderId = intval($payload['orderId'] ?? $payload['order_id'] ?? $payload['id'] ?? $_GET['id'] ?? $_GET['orderId'] ?? 0);\r\n    $payRef = trim(strval($payload['paymentReference'] ?? $payload['payment_reference'] ?? $payload['data']['object']['id'] ?? $_GET['payment_reference'] ?? ''));\r\n    $reason = trim(strval($payload['reason'] ?? $payload['cancel_reason'] ?? 'Cancelado por cliente o pasarela de pago'));\r\n\r\n    if (empty($orderNum) && $orderId <= 0 && empty($payRef)) {\r\n        http_response_code(400);\r\n        echo json_encode(['error' => 'Identificador de pedido no proporcionado (orderNumber, orderId o paymentReference)']);\r\n        exit;\r\n    }\r\n\r\n    $where = [];\r\n    $params = [];\r\n    if (!empty($orderNum)) {\r\n        $where[] = \"`order_number` = :orderNum\";\r\n        $params[':orderNum'] = $orderNum;\r\n    }\r\n    if ($orderId > 0) {\r\n        $where[] = \"`id` = :orderId\";\r\n        $params[':orderId'] = $orderId;\r\n    }\r\n    if (!empty($payRef)) {\r\n        $where[] = \"`payment_reference` = :payRef\";\r\n        $params[':payRef'] = $payRef;\r\n    }\r\n\r\n    $whereClause = implode(' OR ', $where);\r\n    $stmt = $pdo->prepare(\"SELECT id, order_number, status, factusol_order_number, factusol_unstocked FROM `eb_orders` WHERE {$whereClause} LIMIT 1\");\r\n    $stmt->execute($params);\r\n    $existing = $stmt->fetch();\r\n\r\n    if (!$existing) {\r\n        http_response_code(404);\r\n        echo json_encode(['error' => 'Pedido no encontrado para cancelar']);\r\n        exit;\r\n    }\r\n\r\n    $updateStmt = $pdo->prepare(\"\r\n        UPDATE `eb_orders` \r\n        SET `status` = 'CANCELLED',\r\n            `payment_status` = 'CANCELLED'\r\n        WHERE `id` = :id\r\n    \");\r\n    $updateStmt->execute([':id' => $existing['id']]);\r\n\r\n    echo json_encode([\r\n        'success' => true,\r\n        'orderId' => intval($existing['id']),\r\n        'orderNumber' => $existing['order_number'],\r\n        'status' => 'CANCELLED',\r\n        'hadFactusolOrder' => !empty($existing['factusol_order_number']),\r\n        'factusolUnstocked' => intval($existing['factusol_unstocked'] ?? 0),\r\n        'message' => 'Pedido cancelado correctamente en la tienda online',\r\n    ]);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: CHECK_IMAGES (Dirty-Checking de fotos existentes en hosting)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'check_images') {\r\n    $rawBody = file_get_contents('php://input');\r\n    $data = json_decode($rawBody, true) ?: [];\r\n    $imagesToCheck = isset($data['images']) && is_array($data['images']) ? $data['images'] : [];\r\n\r\n    $baseDir = getPublicImagesBaseDir();\r\n    $missing = [];\r\n    $existing = [];\r\n\r\n    foreach ($imagesToCheck as $img) {\r\n        $relPath = is_array($img) ? ($img['path'] ?? '') : strval($img);\r\n        $expectedSize = is_array($img) && isset($img['size']) ? intval($img['size']) : null;\r\n\r\n        $cleanPath = ltrim(str_replace('\\\\', '/', $relPath), '/');\r\n        if (empty($cleanPath) || strpos($cleanPath, '..') !== false) {\r\n            continue;\r\n        }\r\n\r\n        $fullPath = $baseDir . '/' . $cleanPath;\r\n        if (file_exists($fullPath) && is_file($fullPath)) {\r\n            if ($expectedSize !== null && $expectedSize > 0) {\r\n                $actualSize = filesize($fullPath);\r\n                if (abs($actualSize - $expectedSize) <= 10) {\r\n                    $existing[] = $relPath;\r\n                    continue;\r\n                }\r\n            } else {\r\n                $existing[] = $relPath;\r\n                continue;\r\n            }\r\n        }\r\n        $missing[] = $relPath;\r\n    }\r\n\r\n    echo json_encode([\r\n        'success' => true,\r\n        'totalChecked' => count($imagesToCheck),\r\n        'existingCount' => count($existing),\r\n        'missingCount' => count($missing),\r\n        'missing' => $missing,\r\n    ]);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: UPLOAD_IMAGE (Subida directa de fotos por HTTPS)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'upload_image') {\r\n    $targetRelPath = isset($_GET['path']) ? trim($_GET['path']) : '';\r\n    if (empty($targetRelPath) && isset($_SERVER['HTTP_X_FILE_PATH'])) {\r\n        $targetRelPath = trim($_SERVER['HTTP_X_FILE_PATH']);\r\n    }\r\n\r\n    // Saneamiento de seguridad contra Directory Traversal\r\n    $targetRelPath = ltrim(str_replace('\\\\', '/', $targetRelPath), '/');\r\n    if (empty($targetRelPath) || strpos($targetRelPath, '..') !== false) {\r\n        http_response_code(400);\r\n        echo json_encode(['error' => 'Ruta de archivo no especificada o inválida']);\r\n        exit;\r\n    }\r\n\r\n    // Validar extensión de imagen (solo formatos seguros sin SVG para prevenir XSS)\r\n    $ext = strtolower(pathinfo($targetRelPath, PATHINFO_EXTENSION));\r\n    $allowedExts = ['jpg', 'jpeg', 'png', 'webp'];\r\n    if (!in_array($ext, $allowedExts)) {\r\n        http_response_code(400);\r\n        echo json_encode(['error' => 'Extensión de imagen no permitida: ' . $ext . '. Solo se permiten formatos seguros (jpg, jpeg, png, webp)']);\r\n        exit;\r\n    }\r\n\r\n    $tempSource = null;\r\n    $rawContent = null;\r\n    if (isset($_FILES['image']) && is_uploaded_file($_FILES['image']['tmp_name'])) {\r\n        $tempSource = $_FILES['image']['tmp_name'];\r\n    } else if (isset($_FILES['file']) && is_uploaded_file($_FILES['file']['tmp_name'])) {\r\n        $tempSource = $_FILES['file']['tmp_name'];\r\n    } else {\r\n        $rawContent = file_get_contents('php://input');\r\n        if (empty($rawContent)) {\r\n            http_response_code(400);\r\n            echo json_encode(['error' => 'Contenido de imagen vacío']);\r\n            exit;\r\n        }\r\n    }\r\n\r\n    $maxBytes = 10 * 1024 * 1024;\r\n    $allowedMimes = ['image/jpeg', 'image/png', 'image/webp'];\r\n\r\n    if ($tempSource) {\r\n        if (filesize($tempSource) > $maxBytes) {\r\n            http_response_code(400);\r\n            echo json_encode(['error' => 'El tamaño de la imagen supera el límite permitido de 10 MB']);\r\n            exit;\r\n        }\r\n        if (function_exists('finfo_open')) {\r\n            $finfo = finfo_open(FILEINFO_MIME_TYPE);\r\n            $mime = $finfo ? finfo_file($finfo, $tempSource) : '';\r\n            if ($finfo) finfo_close($finfo);\r\n            if (!in_array($mime, $allowedMimes)) {\r\n                http_response_code(400);\r\n                echo json_encode(['error' => 'Tipo MIME no permitido (' . htmlspecialchars($mime) . '). Solo se permiten imágenes JPEG, PNG o WebP']);\r\n                exit;\r\n            }\r\n        }\r\n    } else {\r\n        if (strlen($rawContent) > $maxBytes) {\r\n            http_response_code(400);\r\n            echo json_encode(['error' => 'El tamaño de la imagen supera el límite permitido de 10 MB']);\r\n            exit;\r\n        }\r\n        if (function_exists('finfo_open')) {\r\n            $finfo = finfo_open(FILEINFO_MIME_TYPE);\r\n            $mime = $finfo ? finfo_buffer($finfo, $rawContent) : '';\r\n            if ($finfo) finfo_close($finfo);\r\n            if (!in_array($mime, $allowedMimes)) {\r\n                http_response_code(400);\r\n                echo json_encode(['error' => 'Tipo MIME no permitido (' . htmlspecialchars($mime) . '). Solo se permiten imágenes JPEG, PNG o WebP']);\r\n                exit;\r\n            }\r\n        }\r\n    }\r\n\r\n    $baseDir = getPublicImagesBaseDir();\r\n    $targetFullPath = $baseDir . '/' . $targetRelPath;\r\n    $targetDir = dirname($targetFullPath);\r\n\r\n    if (!is_dir($targetDir)) {\r\n        @mkdir($targetDir, 0755, true);\r\n    }\r\n\r\n    if ($tempSource) {\r\n        $saved = @move_uploaded_file($tempSource, $targetFullPath);\r\n        if (!$saved) {\r\n            $saved = @copy($tempSource, $targetFullPath);\r\n        }\r\n    } else {\r\n        $saved = (file_put_contents($targetFullPath, $rawContent) !== false);\r\n    }\r\n\r\n    if (!$saved) {\r\n        http_response_code(500);\r\n        echo json_encode(['error' => 'No se pudo escribir el archivo en el servidor: ' . $targetRelPath]);\r\n        exit;\r\n    }\r\n\r\n    // Replicación secundaria automática si existe subdirectorio de tienda\r\n    $subdomainCandidates = [\r\n        __DIR__ . '/tienda/assets/img/factusolImg/' . $targetRelPath,\r\n    ];\r\n    foreach ($subdomainCandidates as $subCand) {\r\n        $subDir = dirname($subCand);\r\n        if (is_dir(dirname($subDir))) {\r\n            if (!is_dir($subDir)) @mkdir($subDir, 0755, true);\r\n            @copy($targetFullPath, $subCand);\r\n        }\r\n    }\r\n\r\n    // Actualizar registro del producto en MariaDB si se suministró SKU\r\n    $sku = isset($_GET['sku']) ? trim($_GET['sku']) : (isset($_SERVER['HTTP_X_PRODUCT_SKU']) ? trim($_SERVER['HTTP_X_PRODUCT_SKU']) : null);\r\n    if ($sku) {\r\n        $pdo = getDbConnection();\r\n        if ($pdo) {\r\n            try {\r\n                $canonicalImgPath = (strpos($targetRelPath, '/') === 0) ? $targetRelPath : ('/' . $targetRelPath);\r\n                $updateStmt = $pdo->prepare(\"UPDATE `eb_products` SET `imgart` = :img WHERE `code` = :sku OR `sku` = :sku\");\r\n                $updateStmt->execute([':img' => $canonicalImgPath, ':sku' => $sku]);\r\n            } catch (Exception $e) {}\r\n        }\r\n    }\r\n\r\n    $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';\r\n    $host = $_SERVER['HTTP_HOST'] ?? 'localhost';\r\n    $publicUrl = \"{$scheme}://{$host}/assets/img/factusolImg/{$targetRelPath}\";\r\n\r\n    echo json_encode([\r\n        'success' => true,\r\n        'path' => $targetRelPath,\r\n        'bytesWritten' => filesize($targetFullPath),\r\n        'url' => $publicUrl,\r\n    ]);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: PUSH_CATALOG (Subida masiva de productos desde Bentian Agent)\r\n// ----------------------------------------------------------------------------\r\n$pdo = getDbConnection();\r\nif (!$pdo) {\r\n    http_response_code(500);\r\n    echo json_encode(['error' => 'No se pudo conectar a MariaDB']);\r\n    exit;\r\n}\r\nensureTablesExist($pdo);\r\n\r\n$rawBody = file_get_contents('php://input');\r\n$data = json_decode($rawBody, true) ?: [];\r\n\r\nif ($mainAction === 'push_catalog' || $mainAction === 'sync_catalog') {\r\n    $products = isset($data['products']) && is_array($data['products']) ? $data['products'] : [];\r\n    if (empty($products)) {\r\n        echo json_encode(['success' => true, 'count' => 0, 'message' => 'No se enviaron productos']);\r\n        exit;\r\n    }\r\n\r\n    $sql = \"INSERT INTO `eb_products` \r\n      (`code`, `sku`, `name`, `description`, `section_code`, `section_name`, `family_code`, `family_name`, `price`, `sale_price`, `vat_rate`, `price_with_vat`, `sale_price_with_vat`, `unit_of_measure`, `weight`, `barcode`, `imgart`, `image_url`, `active`, `updated_at`)\r\n    VALUES \r\n      (:code, :sku, :name, :description, :section_code, :section_name, :family_code, :family_name, :price, :sale_price, :vat_rate, :price_with_vat, :sale_price_with_vat, :unit_of_measure, :weight, :barcode, :imgart, :image_url, :active, NOW())\r\n    ON DUPLICATE KEY UPDATE\r\n      `sku` = VALUES(`sku`),\r\n      `name` = VALUES(`name`),\r\n      `description` = VALUES(`description`),\r\n      `section_code` = VALUES(`section_code`),\r\n      `section_name` = VALUES(`section_name`),\r\n      `family_code` = VALUES(`family_code`),\r\n      `family_name` = VALUES(`family_name`),\r\n      `price` = VALUES(`price`),\r\n      `sale_price` = VALUES(`sale_price`),\r\n      `vat_rate` = VALUES(`vat_rate`),\r\n      `price_with_vat` = VALUES(`price_with_vat`),\r\n      `sale_price_with_vat` = VALUES(`sale_price_with_vat`),\r\n      `unit_of_measure` = VALUES(`unit_of_measure`),\r\n      `weight` = VALUES(`weight`),\r\n      `barcode` = VALUES(`barcode`),\r\n      `imgart` = IF(VALUES(`imgart`) != '', VALUES(`imgart`), `imgart`),\r\n      `image_url` = IF(VALUES(`image_url`) != '', VALUES(`image_url`), `image_url`),\r\n      `active` = VALUES(`active`),\r\n      `updated_at` = NOW()\";\r\n\r\n    $stmt = $pdo->prepare($sql);\r\n    $count = 0;\r\n\r\n    $pdo->beginTransaction();\r\n    try {\r\n        foreach ($products as $p) {\r\n            $sku = substr($p['sku'] ?? $p['code'] ?? '', 0, 50);\r\n            $code = substr($p['code'] ?? $sku, 0, 50);\r\n            if (empty($code)) continue;\r\n\r\n            $regPrice = floatval($p['regularPrice'] ?? $p['price'] ?? 0);\r\n            if (!is_finite($regPrice) || $regPrice < 0) $regPrice = 0.0;\r\n            $rawSale = isset($p['salePrice']) ? floatval($p['salePrice']) : null;\r\n            if ($rawSale !== null && (!is_finite($rawSale) || $rawSale < 0)) $rawSale = null;\r\n            $vat = floatval($p['taxRate'] ?? $p['vat_rate'] ?? 21.0);\r\n            if (!is_finite($vat) || $vat < 0) $vat = 21.0;\r\n            $withVat = round($regPrice * (1 + $vat / 100), 4);\r\n            $salePrice = ($rawSale !== null && $rawSale > 0 && $rawSale < $regPrice) ? $rawSale : null;\r\n            $saleWithVat = $salePrice !== null ? round($salePrice * (1 + $vat / 100), 4) : null;\r\n            $weight = floatval($p['weight'] ?? 0);\r\n            if (!is_finite($weight) || $weight < 0) $weight = 0.0;\r\n\r\n            // Normalización canónica de imagen con prefijo /\r\n            $rawImg = '';\r\n            if (!empty($p['imgart'])) {\r\n                $rawImg = $p['imgart'];\r\n            } else if (!empty($p['images']) && is_array($p['images']) && count($p['images']) > 0) {\r\n                $first = $p['images'][0];\r\n                $rawImg = is_array($first) ? ($first['src'] ?? '') : strval($first);\r\n            }\r\n            $cleanImg = '';\r\n            if (!empty($rawImg)) {\r\n                $cleanImg = str_replace('\\\\', '/', $rawImg);\r\n                if (strpos($cleanImg, '/') !== 0 && !preg_match('#^https?://#i', $cleanImg)) {\r\n                    $cleanImg = '/' . $cleanImg;\r\n                }\r\n            }\r\n\r\n            $imgUrl = $p['imageUrl'] ?? $cleanImg;\r\n\r\n            $stmt->execute([\r\n                ':code' => $code,\r\n                ':sku' => $sku,\r\n                ':name' => substr($p['name'] ?? '', 0, 255),\r\n                ':description' => $p['description'] ?? null,\r\n                ':section_code' => substr($p['section_code'] ?? $p['sectionCode'] ?? '', 0, 10) ?: null,\r\n                ':section_name' => substr($p['section_name'] ?? $p['sectionName'] ?? '', 0, 100) ?: null,\r\n                ':family_code' => substr($p['family_code'] ?? $p['familyCode'] ?? '', 0, 10) ?: null,\r\n                ':family_name' => substr($p['family_name'] ?? $p['familyName'] ?? '', 0, 100) ?: null,\r\n                ':price' => $regPrice,\r\n                ':sale_price' => $salePrice,\r\n                ':vat_rate' => $vat,\r\n                ':price_with_vat' => $withVat,\r\n                ':sale_price_with_vat' => $saleWithVat,\r\n                ':unit_of_measure' => substr($p['unitOfMeasure'] ?? 'UNIDADES', 0, 20),\r\n                ':weight' => $weight,\r\n                ':barcode' => substr($p['barcode'] ?? '', 0, 50) ?: null,\r\n                ':imgart' => $cleanImg ?: null,\r\n                ':image_url' => $imgUrl ?: null,\r\n                ':active' => ($p['status'] ?? 'publish') === 'publish' ? 1 : 0,\r\n            ]);\r\n            $count++;\r\n        }\r\n        $pdo->commit();\r\n        echo json_encode(['success' => true, 'count' => $count, 'message' => \"Se actualizaron {$count} productos\"]);\r\n    } catch (Exception $e) {\r\n        $pdo->rollBack();\r\n        http_response_code(500);\r\n        echo json_encode(['error' => 'Fallo al procesar lote de catálogo']);\r\n    }\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: PUSH_STOCK (Actualización rápida de existencias)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'push_stock') {\r\n    $updates = isset($data['stockUpdates']) && is_array($data['stockUpdates']) ? $data['stockUpdates'] : [];\r\n    if (empty($updates)) {\r\n        echo json_encode(['success' => true, 'count' => 0, 'message' => 'No se enviaron existencias']);\r\n        exit;\r\n    }\r\n\r\n    $stmt = $pdo->prepare(\"\r\n        INSERT INTO `eb_stock` (`code`, `stock`, `updated_at`)\r\n        VALUES (:code, :stock, NOW())\r\n        ON DUPLICATE KEY UPDATE `stock` = VALUES(`stock`), `updated_at` = NOW()\r\n    \");\r\n\r\n    $count = 0;\r\n    $pdo->beginTransaction();\r\n    try {\r\n        foreach ($updates as $u) {\r\n            $code = substr($u['code'] ?? $u['sku'] ?? '', 0, 50);\r\n            if (empty($code)) continue;\r\n            $stockVal = floatval($u['stock'] ?? 0);\r\n            if (!is_finite($stockVal)) $stockVal = 0.0;\r\n            $stmt->execute([\r\n                ':code' => $code,\r\n                ':stock' => $stockVal,\r\n            ]);\r\n            $count++;\r\n        }\r\n        $pdo->commit();\r\n        echo json_encode(['success' => true, 'count' => $count]);\r\n    } catch (Exception $e) {\r\n        $pdo->rollBack();\r\n        http_response_code(500);\r\n        echo json_encode(['error' => 'Fallo al actualizar existencias']);\r\n    }\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: PULL_ORDERS (Descarga de pedidos hacia Factusol)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'pull_orders' || $mainAction === 'get_orders') {\r\n    $limit = isset($_GET['limit']) ? max(1, min(100, intval($_GET['limit']))) : 50;\r\n    $stmt = $pdo->prepare(\"SELECT * FROM `eb_orders` WHERE `status` = 'PENDING' ORDER BY `id` ASC LIMIT :lim\");\r\n    $stmt->bindValue(':lim', $limit, PDO::PARAM_INT);\r\n    $stmt->execute();\r\n    $rows = $stmt->fetchAll();\r\n\r\n    $orders = [];\r\n    foreach ($rows as $r) {\r\n        $orders[] = [\r\n            'id' => intval($r['id']),\r\n            'order_number' => $r['order_number'],\r\n            'orderNumber' => $r['order_number'],\r\n            'status' => $r['status'],\r\n            'customer' => json_decode($r['customer_data'], true) ?: [],\r\n            'lines' => json_decode($r['order_lines'], true) ?: [],\r\n            'payment_method' => $r['payment_method'],\r\n            'paymentMethod' => $r['payment_method'],\r\n            'payment_status' => $r['payment_status'] ?? 'COMPLETED',\r\n            'payment_reference' => $r['payment_reference'] ?? '',\r\n            'subtotal' => floatval($r['subtotal'] ?? $r['total']),\r\n            'tax_total' => floatval($r['tax_total'] ?? 0),\r\n            'shipping_cost' => floatval($r['shipping_cost'] ?? 0),\r\n            'total' => floatval($r['total']),\r\n            'created_at' => $r['created_at'],\r\n            'createdAt' => $r['created_at'],\r\n        ];\r\n    }\r\n    echo json_encode(['success' => true, 'orders' => $orders]);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: ACK_ORDERS (Confirmación de pedidos descargados)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'ack_orders') {\r\n    $confirmations = isset($data['confirmations']) && is_array($data['confirmations']) ? $data['confirmations'] : [];\r\n    $stmt = $pdo->prepare(\"\r\n        UPDATE `eb_orders` \r\n        SET `status` = 'SYNCED', \r\n            `factusol_order_number` = :factNum, \r\n            `factusol_series` = :factSer, \r\n            `synced_at` = NOW() \r\n        WHERE `id` = :id\r\n    \");\r\n\r\n    $count = 0;\r\n    $pdo->beginTransaction();\r\n    try {\r\n        foreach ($confirmations as $c) {\r\n            $stmt->execute([\r\n                ':id' => intval($c['orderId'] ?? $c['webOrderId'] ?? $c['id'] ?? 0),\r\n                ':factNum' => intval($c['factusolOrderNumber'] ?? $c['orderNumber'] ?? 0) ?: null,\r\n                ':factSer' => substr($c['factusolSeries'] ?? '1', 0, 5),\r\n            ]);\r\n            $count++;\r\n        }\r\n        $pdo->commit();\r\n        echo json_encode(['success' => true, 'count' => $count]);\r\n    } catch (Exception $e) {\r\n        $pdo->rollBack();\r\n        http_response_code(500);\r\n        echo json_encode(['error' => 'Fallo al confirmar pedidos']);\r\n    }\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: PULL_CANCELLED_ORDERS (Descarga de pedidos cancelados para Factusol)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'pull_cancelled_orders' || $mainAction === 'get_cancelled_orders') {\r\n    $limit = isset($_GET['limit']) ? max(1, min(100, intval($_GET['limit']))) : 50;\r\n    $stmt = $pdo->prepare(\"\r\n        SELECT * FROM `eb_orders` \r\n        WHERE `status` = 'CANCELLED' \r\n          AND `factusol_order_number` IS NOT NULL \r\n          AND (`factusol_unstocked` = 0 OR `factusol_unstocked` IS NULL)\r\n        ORDER BY `id` ASC \r\n        LIMIT :lim\r\n    \");\r\n    $stmt->bindValue(':lim', $limit, PDO::PARAM_INT);\r\n    $stmt->execute();\r\n    $rows = $stmt->fetchAll();\r\n\r\n    $orders = [];\r\n    foreach ($rows as $r) {\r\n        $orders[] = [\r\n            'id' => intval($r['id']),\r\n            'order_number' => $r['order_number'],\r\n            'orderNumber' => $r['order_number'],\r\n            'status' => $r['status'],\r\n            'customer' => json_decode($r['customer_data'], true) ?: [],\r\n            'lines' => json_decode($r['order_lines'], true) ?: [],\r\n            'payment_method' => $r['payment_method'],\r\n            'paymentMethod' => $r['payment_method'],\r\n            'payment_status' => $r['payment_status'] ?? 'CANCELLED',\r\n            'payment_reference' => $r['payment_reference'] ?? '',\r\n            'subtotal' => floatval($r['subtotal'] ?? $r['total']),\r\n            'tax_total' => floatval($r['tax_total'] ?? 0),\r\n            'shipping_cost' => floatval($r['shipping_cost'] ?? 0),\r\n            'total' => floatval($r['total']),\r\n            'factusol_order_number' => intval($r['factusol_order_number']),\r\n            'factusolOrderNumber' => intval($r['factusol_order_number']),\r\n            'factusol_series' => $r['factusol_series'] ?? '1',\r\n            'factusolSeries' => $r['factusol_series'] ?? '1',\r\n            'created_at' => $r['created_at'],\r\n            'createdAt' => $r['created_at'],\r\n        ];\r\n    }\r\n    echo json_encode(['success' => true, 'orders' => $orders]);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: ACK_CANCELLED_ORDERS (Confirmación de reposición de stock en Factusol)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'ack_cancelled_orders') {\r\n    $confirmations = isset($data['confirmations']) && is_array($data['confirmations']) \r\n        ? $data['confirmations'] \r\n        : (isset($data['orderIds']) && is_array($data['orderIds']) ? $data['orderIds'] : []);\r\n\r\n    $stmt = $pdo->prepare(\"\r\n        UPDATE `eb_orders` \r\n        SET `factusol_unstocked` = 1, \r\n            `unstocked_at` = NOW() \r\n        WHERE `id` = :id\r\n    \");\r\n\r\n    $count = 0;\r\n    $pdo->beginTransaction();\r\n    try {\r\n        foreach ($confirmations as $c) {\r\n            $orderId = is_array($c) \r\n                ? intval($c['orderId'] ?? $c['webOrderId'] ?? $c['id'] ?? 0)\r\n                : intval($c);\r\n            if ($orderId > 0) {\r\n                $stmt->execute([':id' => $orderId]);\r\n                $count++;\r\n            }\r\n        }\r\n        $pdo->commit();\r\n        echo json_encode(['success' => true, 'count' => $count]);\r\n    } catch (Exception $e) {\r\n        $pdo->rollBack();\r\n        http_response_code(500);\r\n        echo json_encode(['error' => 'Fallo al confirmar reposición de pedidos cancelados']);\r\n    }\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: CLEAN_TEST_DATA (Eliminación de artículos y pedidos de prueba)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'clean_test_data' || $mainAction === 'delete_test_data') {\r\n    $pdo = getDbConnection();\r\n    ensureTablesExist($pdo);\r\n\r\n    $delProd = $pdo->exec(\"DELETE FROM `eb_products` WHERE `code` = '000001' OR `name` LIKE '%Taladro Percutor%' OR `code` LIKE 'TEST%'\");\r\n    $delStock = $pdo->exec(\"DELETE FROM `eb_stock` WHERE `code` = '000001' OR `code` LIKE 'TEST%'\");\r\n    $delOrders = $pdo->exec(\"DELETE FROM `eb_orders` WHERE `order_number` LIKE '%PRUEBA%' OR `order_number` LIKE '%TEST%' OR `customer_data` LIKE '%test@test.com%'\");\r\n\r\n    echo json_encode([\r\n        'success' => true,\r\n        'deletedProducts' => intval($delProd),\r\n        'deletedStock' => intval($delStock),\r\n        'deletedOrders' => intval($delOrders),\r\n        'message' => 'Datos de prueba eliminados correctamente de la base de datos de la tienda online',\r\n    ]);\r\n    exit;\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// ACCIÓN PROTEGIDA: DELETE_PRODUCT (Eliminación de artículo individual por código)\r\n// ----------------------------------------------------------------------------\r\nif ($mainAction === 'delete_product' || $mainAction === 'delete_article') {\r\n    $code = trim($_GET['code'] ?? $data['code'] ?? $data['codart'] ?? '');\r\n    if (empty($code)) {\r\n        http_response_code(400);\r\n        echo json_encode(['error' => 'Código de artículo no especificado (parámetro code)']);\r\n        exit;\r\n    }\r\n    $pdo = getDbConnection();\r\n    ensureTablesExist($pdo);\r\n    $stmt1 = $pdo->prepare(\"DELETE FROM `eb_products` WHERE `code` = :code\");\r\n    $stmt1->execute([':code' => $code]);\r\n    $stmt2 = $pdo->prepare(\"DELETE FROM `eb_stock` WHERE `code` = :code\");\r\n    $stmt2->execute([':code' => $code]);\r\n    echo json_encode([\r\n        'success' => true,\r\n        'code' => $code,\r\n        'message' => \"Artículo {$code} eliminado correctamente de la tienda web\",\r\n    ]);\r\n    exit;\r\n}\r\n\r\nhttp_response_code(400);\r\necho json_encode(['error' => 'Acción no válida: ' . htmlspecialchars($mainAction)]);\r\n";
